Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <algorithm>
#include <iostream>
#include <cstdio>
#include <vector>
#include <deque>
using namespace std;
vector<int> e[2020];
int ir[20][20];
int sc[20][20];
int pc[20][20];
char s[20][20];
char p[20][20];
int dd[20][20];
int dx[5]={0,1,-1,0};
int dy[5]={1,0,0,-1};
vector<int> ns[20][20],np[20][20];
void ade(int a,int b)
{
    e[a].push_back(b);
    e[b].push_back(a);
}
int ds[2020];
int pa[2020];
int sp,pp;
bool bfs()
{
    deque<int> q;
    for(int i=1;i<=sp;i++)
    {
        if(pa[i]==0)
            ds[i]=0,q.push_back(i);
        else
            ds[i]=3010;
    }
    ds[0]=3010;
    while(!q.empty())
    {
        int u=q[0];
        q.pop_front();
        if(ds[u]<ds[0])
        {
            for(int i=0;i<e[u].size();i++)
            {
                int v=pa[e[u][i]];
                if(ds[v]>ds[u]+1)
                    ds[v]=ds[u]+1,q.push_back(v);
            }
        }
    }
    return ds[0]!=3010;
}
bool dfs(int x)
{
    if(x==0)
        return 1;
    for(int i=0;i<e[x].size();i++)
    {
        int u=pa[e[x][i]];
        if(ds[u]==ds[x]+1)
        {
            if(dfs(u))
            {
                pa[x]=e[x][i];
                pa[e[x][i]]=x;
                return 1;
            }
        }
    }
    return 0;
}
int hkp()
{
    int an=0;
    while(bfs())
    {
        for(int i=1;i<=sp;i++)
        {
            if(pa[i]==0)
                an+=dfs(i);
        }
    }
    return an;
}
int n,t;
void wk(int a,int b)
{
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            dd[i][j]=100000;
        }
    }
    deque<pair<int,int> > q;
    dd[a][b]=0;
    q.push_back(make_pair(a,b));
    while(!q.empty())
    {
        int x=q[0].first,y=q[0].second;
        q.pop_front();
        for(int i=0;i<np[x][y].size();i++)
            for(int j=0;j<ns[a][b].size();j++)
                ade(ns[a][b][j],np[x][y][i]);
        if(dd[x][y]==ir[x][y])
            continue;
        for(int d=0;d<4;d++)
        {
            int nx=x+dx[d];
            int ny=y+dy[d];
            if(sc[nx][ny]!=-1&&dd[nx][ny]>dd[x][y]+1&&dd[x][y]+1<=ir[nx][ny])
            {
                dd[nx][ny]=dd[x][y]+1;
                q.push_back(make_pair(nx,ny));
            }
        }
    }
}
int main()
{
    scanf("%d%d",&n,&t);
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
            ir[i][j]=t;
    for(int i=1;i<=n;i++)
        scanf("%s",s[i]+1);
    for(int i=1;i<=n;i++)
        scanf("%s",p[i]+1);
    int rx,ry;
    sp=1,pp=1000;
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            if(s[i][j]=='Z'||s[i][j]=='Y')
                sc[i][j]=-1,ir[i][j]=0;
            if(s[i][j]=='Z')
                rx=i,ry=j,ir[i][j]=0;
            if('0'<=s[i][j]&&s[i][j]<='9')
                sc[i][j]=s[i][j]-'0';
            for(int k=0;k<sc[i][j];k++)
                ns[i][j].push_back(sp++);
        }
    }
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            if('0'<=p[i][j]&&p[i][j]<='9')
                pc[i][j]=p[i][j]-'0';
            for(int k=0;k<pc[i][j];k++)
                np[i][j].push_back(pp++);
        }
    }
    deque<pair<int,int> > q;
    q.push_back(make_pair(rx,ry));
    while(!q.empty())
    {
        rx=q[0].first,ry=q[0].second;
        q.pop_front();
        int nx,ny;
        for(int d=0;d<4;d++)
        {
            nx=rx+dx[d];
            ny=ry+dy[d];
            if(ir[nx][ny]>ir[rx][ry]+1&&sc[nx][ny]!=-1)
            {
                ir[nx][ny]=ir[rx][ry]+1;
                q.push_back(make_pair(nx,ny));
            }
        }
    }
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            if(sc[i][j]>0)
            {
                wk(i,j);
            }
        }
    }
    printf("%d",hkp());
}

</original_code>
